def sum_column(table, column):
    """
    Sums the values in the specified column of a table.

    Parameters:
    - table: list of dicts or list of lists (or tuples).
    - column: if table is list of dicts, column is the key;
              if table is list of lists, column is the index (int).

    Returns:
    - sum of numeric values in the column; non-numeric or missing values are ignored.
    """
    total = 0
    for row in table:
        try:
            # if dict
            if isinstance(row, dict):
                value = row.get(column)
            else:
                # assume list/tuple; column must be int index
                value = row[column]
            if isinstance(value, (int, float)):
                total += value
        except (IndexError, KeyError, TypeError):
            # skip rows with missing column or wrong types
            continue
    return total

