def is_decimal(value) -> bool:
    try:
        s = str(value).strip()
        if '.' not in s:
            return False
        integer_part, decimal_part = s.split('.', 1)
        # Check if decimal part has exactly two digits and both parts are numeric (allow leading + or -)
        if len(decimal_part) != 2:
            return False
        # Check integer part (allow sign)
        int_check = integer_part.lstrip('+-')
        if not int_check.isdigit():
            return False
        if not decimal_part.isdigit():
            return False
        return True
    except Exception:
        return False

