def min_Jumps(d, length):
    d = abs(d)
    if d == 0:
        return 0
    if d == length:
        return 1
    if d < length:
        return 2
    # For d > length:
    n = d / length
    if n.is_integer():
        return int(n)
    else:
        # Check if it is possible to reach exactly (d,0) with n+1 jumps:
        # Because each jump is length, and we can move in any direction,
        # the minimal number of jumps needed is the minimal n such that
        # n*length >= d and also the distance d can be formed as sum of n vectors of length length.
        # If d > length and not divisible, at least ceil(d/length) jumps are needed.
        return math.ceil(n)

