def anti_shuffle(s):
    words = s.split(' ')
    result_words = []
    for w in words:
        if len(w) <= 1:
            result_words.append(w)
        else:
            # Sort characters in the word
            sorted_w = ''.join(sorted(w))
            result_words.append(sorted_w)
    # Join words with single spaces to preserve original spacing between words
    # but since split(' ') splits on single space, multiple spaces would be lost.
    # To preserve spacing exactly, process the string differently.
    # However, the task says "keep the order of words and blank spaces".
    # So we need to preserve spaces as well.
    # The above approach loses multiple spaces.

    # So instead of split(' '), use re to split with capturing spaces
    import re
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            result.append(part)
        else:
            if len(part) <= 1:
                result.append(part)
            else:
                result.append(''.join(sorted(part)))
    return ''.join(result)

